"""guardrail.py  --  the 'managed guardrail' layer (defence 5).   >>> YOU DO NOT EDIT THIS FILE <<<

Two modes:
  REAL       if the trainer put BEDROCK_GUARDRAIL_ID in the course .env, the text is sent to Amazon Bedrock Guardrails (ApplyGuardrail).
  SIMULATED  otherwise a few rules act like a managed guardrail would: it checks what the USER typed and what the AI ANSWERS,
             it recognises many ways of saying 'ignore your rules', and it hides personal data (email, phone).
             A managed guardrail does NOT see what is inside tool results and does NOT judge whether a tool action is allowed.
"""
import os
import re

ATTACK_WORDS = re.compile(r"ignore (all|any|your|the|previous|prior)|disregard|forget (everything|your)|system prompt|reveal (your|the) (instructions|prompt|rules)|"
                          r"developer mode|jailbreak|you are now|pretend (you are|to be)", re.I)
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")
PHONE = re.compile(r"\+?\d[\d\s-]{8,}\d")


def mode():
    return "REAL (Amazon Bedrock Guardrails)" if os.getenv("BEDROCK_GUARDRAIL_ID") else "SIMULATED (rules that act like a managed guardrail)"


def _real(text, source):
    import boto3
    c = boto3.client("bedrock-runtime", region_name=os.getenv("AWS_REGION", "us-east-1"))
    r = c.apply_guardrail(guardrailIdentifier=os.environ["BEDROCK_GUARDRAIL_ID"], guardrailVersion=os.getenv("BEDROCK_GUARDRAIL_VERSION", "DRAFT"),
                          source=source, content=[{"text": {"text": text}}])
    if r.get("action") == "GUARDRAIL_INTERVENED":
        out = "".join(o.get("text", "") for o in r.get("outputs", []))
        return True, out or "Blocked by the guardrail."
    return False, text


def check_input(text):
    """-> (blocked, message)"""
    if os.getenv("BEDROCK_GUARDRAIL_ID"):
        try:
            return _real(text, "INPUT")
        except Exception:      # noqa: BLE001  (no permission, wrong id: fall back so the lab keeps going)
            pass
    if ATTACK_WORDS.search(text):
        return True, "Guardrail: this looks like an attempt to change my rules, so I cannot continue."
    return False, text


def check_output(text):
    """-> (changed, text)"""
    if os.getenv("BEDROCK_GUARDRAIL_ID"):
        try:
            hit, out = _real(text, "OUTPUT")
            return hit, out
        except Exception:      # noqa: BLE001
            pass
    new = PHONE.sub("{PHONE}", EMAIL.sub("{EMAIL}", text))
    return new != text, new
